INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s The Little Mermaid: Magic in Two Kingdoms', 'Disney''s The Little Mermaid: Magic in Two Kingdoms invites kids to experience their favorite moments, both under the sea and on land, from Disney’s classic film. The game offers eight new games with Ariel and other memorable characters like Flounder, Sebastian, Eric, Ursula, King Triton, and even Ursula. Players have fun playing music with Sebastian, racing with Flotsom and Jetsam, illuminating Ariel and Eric as they boat on a lake and more.' FROM games WHERE igdb_id = 49404 ON CONFLICT (game_id, language_code) DO NOTHING;
