INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bang! Howdy', 'Bang Howdy! is an online free-to-play strategy game. The setting mixes elements from a variety of related genres, such as steampunk or Native American myth. Several of the players'' available units are entirely mechanical, including artillery and a "steam gunman", a robot boasting large wagon wheels for movement while wearing a cowboy hat. Other, more conventional units include cavalry and gunslingers.' FROM games WHERE igdb_id = 51472 ON CONFLICT (game_id, language_code) DO NOTHING;
