INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 2000 Series Vol. 98: The Roman Sabou', 'The Roman Sabou: In the game the player takes the role of the only daughter of a family that will have to run a sweet shop during a year of time. The game features over 884 different sweets to make. During the game the player will go with one of the 6 different boys to different places around the town to look for new ingredients for the different sweets, and also check often the balance of the money''s shop since if there are loses at the end of any of the months is game over.' FROM games WHERE igdb_id = 203329 ON CONFLICT (game_id, language_code) DO NOTHING;
