INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('samurai-warriors-2-empires', 7174, '2006-11-16', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9bkb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/w71jkgasszxxg3g7lgfk.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Warriors 2 Empires', 'Samurai Warriors 2 Empires is an expansion to the original Samurai Warriors 2 and the third Empires expansion by Koei. Very similar to both Dynasty Warriors 4 Empires and Dynasty Warriors 5 Empires, the game features the strategic and tactical Empire Mode that combines the gameplay of Samurai Warriors and several turn-based strategy elements from Nobunaga''s Ambition and Romance of the Three Kingdoms. The Empire mode allows the player to select from some of Japan''s greatest battles. In the CAW Mode, the options are limited to 13 models with 10 color patterns each, as well as four different voices. Fortunately, a new feature is added to the mix: the ability to copy movesets of other characters. Unlike Samurai Warriors: Xtreme Legends, the game does not feature new characters for the series. However, Sasaki Kojiro and Shibata Katsuie, who were unplayable special bodyguards in the original Samurai Warriors 2, are now playable characters in Samurai Warriors 2 Empires.' FROM games WHERE igdb_id = 7174 ON CONFLICT (game_id, language_code) DO NOTHING;
