INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Growlanser: Heritage of War', 'Growlanser: Heritage of War features a sweeping story arc spanning 5 chapters, with additional chapters to unlock. On an island continent shrouded in darkness and bounded on every shore by an impassable veil, war rages among desperate inhabitants fighting for survival. There is no safe haven; land that war has left untouched is still threatened by the Screapers, fierce and powerful monsters steadily encroaching on the cities of men - who will rise to save this dying land?' FROM games WHERE igdb_id = 21308 ON CONFLICT (game_id, language_code) DO NOTHING;
