INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Quest Monsters: Joker', 'Players assume the role of a monster hunter as they capture, train and breed a powerful army from more than 200 classic Dragon Quest creatures in order to become the world''s greatest monster trainer. Joker is a breakout title that combines the depth of a classic Dragon Quest RPG with the addictiveness of a monster catching adventure.' FROM games WHERE igdb_id = 17460 ON CONFLICT (game_id, language_code) DO NOTHING;
