INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('samurai-champloo-sidetracked', 19625, '2006-02-23', 63, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co50it.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Champloo: Sidetracked', 'Samurai Champloo steps out of the hack-and-slash action genre and offers a new way to swing a finely-honed samurai blade. Set in Japan with hip hop feel from the hit TV series by the same name, this title allows gamers to breathe life to a "lost episode" as one of three playable characters - Mugen, a reckless samurai with break-dancing fighting style, calculated Jin who abides by the decorum of Bushido, and a mysterious new character exclusive to the video game. Stranded in northern land of Ezo (current day Hokkaido) in search of the samurai who smells of sunflowers, the player must face foreign mercenaries, master swordsmen, diabolical assassins, mythical beasts, and gangster monkeys. The core of the game''s unique combat system lies in the innovative integration of music and linked attacks. The players can choose an array of combos based on the different hip hop grooves that they can swap at will. Music tracks become collectible, opening an extensive assortment of linked attacks that can be implemented tactically during combat.' FROM games WHERE igdb_id = 19625 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 19625 AND ge.slug = 'hack-and-slash-beat-em-up' ON CONFLICT DO NOTHING;
