INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dot-fighters', 234832, '2006-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coaesn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sckw09.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dot Fighters', 'Dot Fighters is a 2006 2D Fighter Maker doujin game by Takase, the guy who made Arm Joe. It only contains 4 characters drawn in an extremely retro, pixel-art style. Despite the small amount of content, it is pretty infamous for its larger filesize. It contains a full soundtrack and voice acting. The game requires that your computer''s locale be set to Japanese in order to play.
