INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dynasty Warriors 5: Empires', 'Dynasty Warriors 5 Empires (真･三國無双4 Empires) is the second expansion for Dynasty Warriors 5. Like the previous Empires expansion, the game focuses on the player''s ability to simulate a leader taking and controlling territory, eventually becoming a powerful leader controlling China. They can form helpful alliances with other factions, recruit powerful officers to their side, use tactics to gain the upper hand against foes, etc.' FROM games WHERE igdb_id = 19624 ON CONFLICT (game_id, language_code) DO NOTHING;
