INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SuperTuxKart', 'SuperTuxKart, also known as STK, is a free and open-source kart racing video game featuring the Linux mascot Tux. SuperTuxKart is cross-platform, running on Windows, OS X, Linux, AmigaOS 4, AROS, MorphOS and other Unix systems. The latest stable version of the game is version 1.3 and was released on September 28, 2021.
