INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thrillville', 'Thrillville allows gamers of all ages to easily build and customize the coaster of your dreams. Imagination is the only height limit with Thrillville, where the fun ranges from racing on go-kart tracks you put together and playing mini-golf on courses you designed to joining friends for dozens of four-player party games, from bumper cars to arcade shoot-''em-ups. You can also tour the park on foot, chatting and joking with all the guests to help them out and make sure they''re enjoying themselves.' FROM games WHERE igdb_id = 2852 ON CONFLICT (game_id, language_code) DO NOTHING;
