INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kaitou-rousseau', 214573, '2006-06-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6s8d.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scrrpt.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kaitou Rousseau', 'In Kaitou Rousseau (aka. Rousseau the Thief), you take the role as a thief who is trying to hide from the police. Rousseau has one very tricky ability, which is to change the shape and look of his face. By drawing images on the Nintendo DS touch screen, you can adapt Rousseau to the current surroundings and thereby evade his chasers. For example, you can draw a picture of a girl to throw off the cops when in a crowd or quickly sketch what''s on a nearby wall to blend in with the background.' FROM games WHERE igdb_id = 214573 ON CONFLICT (game_id, language_code) DO NOTHING;
