INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('archlord', 20598, '2006-11-03', 40, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6jvo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/u2arvoigimtpciseujbk.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ArchLord', 'In this massively-multiplayer online game, ArchLord features an advanced player-vs-player combat system, utilizing sprawling free battle areas and special guild battlefields that enables players to battle in fearsome guild versus guild battles. With an ever-evolving storyline of conquest and betrayal, ArchLord presents an epic adventure in which players band together as they quest for the ancient relics of the Archons. Each relic bestows incredible power on those who possess it and when relics are combined they deliver ultimate mastery over the fundamental forces of creation for there can only be one Archlord! Every month, one player will take control of the world, and with it the opportunity to wreak havoc on their cowering enemies as the player gains control of supreme global Archlord powers!' FROM games WHERE igdb_id = 20598 ON CONFLICT (game_id, language_code) DO NOTHING;
