INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Game Tycoon', 'Game Tycoon welcomes you to the ground floor of a massive new industry. It''s 1982 and you & some friends are discovering the wonders of the personal computer. When you realize the potential for creating a new kind of game for them - "video games" - you decide to start a new business dedicated to it. You picked the right time -- the gaming revolution is about to begin. Can you become the biggest player in the industry, or will your little company fade out and disappear?' FROM games WHERE igdb_id = 127332 ON CONFLICT (game_id, language_code) DO NOTHING;
