INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cartoon Network Racing', 'Cartoon Network Racing provides gamers with endless hours of fun with 24 different racing circuits for players to zoom round. Racing zones include Spooky Mine and the Theme Park, plus -show-themed- locations such as Dexter''s Laboratory and the Aron City. Players can enjoy the game alone in single player mode, or go head-to-head with an opponent or race as driver and co-driver in the two-player mode.' FROM games WHERE igdb_id = 2785 ON CONFLICT (game_id, language_code) DO NOTHING;
