INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetris New Century', 'Brand new and exclusive to Sega Ages 2500 Series Vol. 28: Tetris Collection is "Tetris New Century", which builds upon the 1988 System 16 version of Tetris. New Century implements many of the standards set by The Tetris Company, including the standardised colour scheme, wall kicks, being able to "hold" a piece and the "T-Spin" move (allowing you spin a T-tetromino to fill in gaps shortly before the piece locks into place).' FROM games WHERE igdb_id = 236719 ON CONFLICT (game_id, language_code) DO NOTHING;
