INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rikorisu-lycoris-radiata', 77864, '2006-03-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9m45.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvys7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rikorisu: Lycoris Radiata', 'After questioning his path in life, Touwa embarks on a soul-searching journey across the open sea. Stranded under the scorching sun with no wind, his desperate prayers for relief are answered by a sudden storm that leaves him shipwrecked on an uncharted island. There, he discovers a mansion inhabited by three sister maids who offer him shelter as he works to repair his ship and continue his journey.' FROM games WHERE igdb_id = 77864 ON CONFLICT (game_id, language_code) DO NOTHING;
