INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Onechanbara: Bikini Samurai Squad', 'Play with a friend in co-op mode or switch between any of the three beautiful playable characters in single-player in Onechanbara: Bikini Samurai Squad. Each character has a variety of unique moves to master during combat to destroy enemy zombies. Get blood on either sister to trigger Rage Mode and gain more power and agility to destroy enemies faster and deadlier. For an added experience, go to Marketplace to download additional outfits and sword-flinging girls.' FROM games WHERE igdb_id = 5086 ON CONFLICT (game_id, language_code) DO NOTHING;
