INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bode Miller Alpine Skiing', 'With Bode Miller Alpine Skiing you can select a pre-existing skier or create your own. Either way, you take your skier and build them into a top Alpine athlete. Remember, though that behind every great athlete is a great manager and trainer, and this game makes no exception.' FROM games WHERE igdb_id = 43553 ON CONFLICT (game_id, language_code) DO NOTHING;
