INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'True Remembrance', 'True Remembrance is an ordinary tale of the ordinary days spent in an ordinary town by an ordinary girl who learns that everything in this world is extraordinary - or that nothing is. For in this world, there is a young man named Blackiris; a Mnemonicide par excellence. And there is a young girl named La; sweet and warm and gentle in all the ways that count. This is their story.' FROM games WHERE igdb_id = 78939 ON CONFLICT (game_id, language_code) DO NOTHING;
