INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Rising', 'Frank West, a freelance photojournalist on the hunt for the scoop of a lifetime, pursues a juicy lead to a small suburban town only to find that it is being overrun by zombies! He escapes to the local shopping mall thinking it will be a bastion of safety, but it turns out to be anything but. It''s a true struggle to survive the endless stream of enemies, but with full reign over an entire shopping center, Frank can utilize anything to fight off the flesh-hungry mob and search for the truth behind the horrendous epidemic.' FROM games WHERE igdb_id = 4797 ON CONFLICT (game_id, language_code) DO NOTHING;
