INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Castlevania: Portrait of Ruin', 'Castlevania: Portrait of Ruin is a side-scrolling action RPG where you switch between two hunters, Jonathan Morris and Charlotte Aulin, to explore Dracula''s castle and defeat the vampire Brauner. Set in 1944, Jonathan wields the Vampire Killer whip while Charlotte casts magic. You''ll navigate eight painted worlds hidden within the castle, solve puzzles using each character''s unique abilities, and acquire new skills and weapons. Your decisions determine which of multiple endings you receive.' FROM games WHERE igdb_id = 1138 ON CONFLICT (game_id, language_code) DO NOTHING;
