INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hi-hi-puffy-ami-yumi-genie-and-the-amp', 84521, '2006-06-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/rskxzzlfzej9kwp8ylku.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ly7m4wqado0szfzzj21k.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hi Hi Puffy Ami Yumi: Genie & The Amp', 'Available for the first time ever on Nintendo DS, Hi Hi Puffy AmiYumi: Genie & the Amp follows the fantastic adventures of two very cool pop stars from Cartoon Network’s animated rock series Hi Hi Puffy AmiYumi. The girls are way behind in recording their new album because they’ve tripped over a massive writer’s block. Luckily, they discover a genie behind a dusty amplifier who helps them battle across 10 unique time periods such as Ancient Rome and the Wild Wild West, to gain the musical notes needed to play the ultimate world tour. Fans will play as Ami or Yumi as they use their skills to solve challenging puzzles, battle scary enemies and unlock fun mini-games in single player mode or multiplayer cooperative mode for up to two players via the wireless feature for Nintendo DS.' FROM games WHERE igdb_id = 84521 ON CONFLICT (game_id, language_code) DO NOTHING;
