INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rengoku II: The Stairway to H.E.A.V.E.N.', 'Rengoku 2 builds upon the first game with improved level design for more strategy, smoother control, exciting new fighting mechanics that allow for attack combos, and deeper customization. With network support for up to four players, more levels, an explosive soundtrack and character designs by Jun Suemi, Rengoku 2 is a deep and more challenging action experience.' FROM games WHERE igdb_id = 24185 ON CONFLICT (game_id, language_code) DO NOTHING;
