INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kero Kero 7', 'Kero Kero 7 features an assortment of spy tools for players to use. Record a voice sample and save it or send it to friends. Use your built-in stopwatch or set an alarm. Scribble away with your very own drawing tools! Annoy your friends with your own personal sound effect generator! Or share your secret agent data card with friends who have a copy of the game!' FROM games WHERE igdb_id = 72284 ON CONFLICT (game_id, language_code) DO NOTHING;
