INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tomb-raider-the-action-adventure', 123009, '2006-11-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3lyn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sccqrr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tomb Raider: The Action Adventure', 'Tomb Raider: The Action Adventure is an interactive movie based on Tomb Raider: The Angel of Darkness. The game does not only feature the same story line as that game, it is entirely built around video footage of it. Therefore the player sees Lara from a third-person perspective like in other games in the series as she runs, jumps and climbs around the levels, but for most of the time there is no control over her movement. At certain times the video stops and the player gets to choose what Lara should do next.
