INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('babo-violent-2', 72760, '2006-10-10', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/wxac9jipvbjdzhpgli0a.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Babo Violent 2', 'Babo Violent 2 is a freeware multiplayer game for Windows. It is a 3d Top-down shooter. The game is played over the Internet or a LAN. There are a variety of game modes to choose from, ranging from the free-for-all (Deathmatch) to the team-based (Capture the Flag). In some modes holding or defending a flag is the primary goal, where in others it is simply to obtain the most frags. For all game modes, the basic objective is to kill enemy players. Before spawning, the player is presented with a large arsenal of weapons to choose from. A few grenades and a molotov cocktail are also supplied by default and more grenades can be picked up from the ground. Some servers enable secondary functions like knives, shields or nuclear kamikaze attacks. Upon death players leave behind a health pack for healing injury, the weapon and any equipped grenades for others to pick up. After waiting for a server-specified amount of time (usually less than five seconds), players respawn and may choose another weapon—this cycle repeats for the duration of the map. After a certain allotted time (usually 15 minutes), the map changes and scores are reset as players continue in another round. Players can chat with each other throughout matches (and to their own teams, for cooperative team-based game modes).' FROM games WHERE igdb_id = 72760 ON CONFLICT (game_id, language_code) DO NOTHING;
