INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Office Wars', 'Office Wars was a casual, strategy-laced Facebook/social game launched around July 2010 by Broken Bulb Studios . In this tongue-in-cheek office simulator, players manage a team of quirky employees outfitted with absurd weapons (think giant shrimp, staplers, etc.) to "battle" rival office workers across cubicle corridorsO' FROM games WHERE igdb_id = 354819 ON CONFLICT (game_id, language_code) DO NOTHING;
