INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dreamfall: The Longest Journey', 'Dreamfall: The Longest Journey, winner of multiple E3 awards as the best game in its genre, is the continuation of a saga that began in the award-winning The Longest Journey, considered to be one of the finest adventure games ever made. In Dreamfall, players are taken on an epic journey of exploration and adventure as they venture through a thrilling and emotional storyline. Dreamfall features a fully interactive world where beautiful music, stunning graphics, fascinating characters and unparalleled gameplay variety promises to bring the adventure genre into a new era. Prepare for a spiritual, fantastic and powerful gaming experience.' FROM games WHERE igdb_id = 1961 ON CONFLICT (game_id, language_code) DO NOTHING;
