INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Codename Kids Next Door: Tummy Trouble', 'Cafeteria Reconnaissance has revealed the entrance to Gramma Stuffum`s Sinister Kitchen complex. This facility must be neutralized. Her campaign to fatten up the world`s children has incapacitated our entire task force. You are the only one left, Numbuh 1. Do not fail.' FROM games WHERE igdb_id = 349934 ON CONFLICT (game_id, language_code) DO NOTHING;
