INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arena Football', 'The speed. The scoring. The spectacle. Experience the intensity and passion of the indoor gridiron for the first time with EA Sports Arena Football. All the devastating hits and non-stop passing thrills are brought to life as you''re put in the middle of the action from opening day all the way to the Arena Bowl. Rediscover football and play the game in a new way with EA Sports Arena Football.' FROM games WHERE igdb_id = 5731 ON CONFLICT (game_id, language_code) DO NOTHING;
