INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Diner Dash: Flo on the Go', 'The famous Flo is back but this time she''s traded in her apron for a passport to paradise! With all the hustle and bustle ... will our hard-working waitress get a chance to relax? Help Flo seat customers, take orders, collect tips and dress her up in hundreds of vacation outfits in the all-new Flo''s Closet. New thrills, spills, and a surprise restaurant await you in the third episode of the original smash hit.' FROM games WHERE igdb_id = 24336 ON CONFLICT (game_id, language_code) DO NOTHING;
