INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dynasty-warriors-vol-2', 42886, '2006-03-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6g1i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmd9g.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dynasty Warriors Vol. 2', 'Ancient China''s greatest warriors have rocked the foundations of heaven and earth for over 2,000 years. Now KOEI''s ''Warriors Worth a Thousand'' return in a sequel that eclipses the original with an exquisite array of features. For the first time, up to 4 players can engage in multiplayer combat including a Battle Royal mode. Players can now unlock up to 300 officers (three times as many as the original), and then wirelessly trade these officers with other players. Players can also manage a stable of up to 8 horses and elephants. Each mount will gain experience during battle and will prove a valuable military asset when setting out to conquer the game''s more than 50 stages and 31 maps. Dynasty Warriors Vol. 2 includes the complete pantheon of all 48 Dynasty Warriors, with branching story paths for each kingdom. Game modes include Musou, Multiplayer and Free mode, plus a Camp mode where players can view detailed information on weapons, officers and stages. The game also gives players a full view of the battlefield action using the PSP system''s wide-screen display.' FROM games WHERE igdb_id = 42886 ON CONFLICT (game_id, language_code) DO NOTHING;
