INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('eve-new-generation', 70779, '2006-08-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co49yp.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'EVE: New Generation', 'In this installment of the EVE series, the two protagonists are once again the young careless private detective Kojiroh Amagi, and the sexy government agent Marina Houjou. Five years have passed since the events described in EVE: The Fatal Attraction. One day, Kojiroh bumps into a young girl on the street, accompanied by a foreigner. Immediately afterwards he receives a call from his ex-girlfriend, who tells him a girl has been kidnapped, and sends him a picture of that girl. To his astonishment, Kojiroh realizes this is the very same girl he just saw on the street... Meanwhile, Marina encounters a young man who jumps from the roof of a high building in front of her eyes. Examining the body, Marina notices a strange tattoo on the young man''s hand. What was the reason for the suicide? What is the meaning of the tattoo? And how is this case connected to the one Kojiroh is investigating? Like all the previous EVE games, this is a traditional Japanese adventure without puzzles. The standard menu-based and point-and-click interfaces are replaced by a new one; whenever you have the freedom of action, you press a combination of buttons on your gamepad. For example, circle button and the left directional button pressed together will make you examine the objects you see to your left, etc. True to the tradition of EVE series, you control both Kojiroh and Marina. You can switch between their scenarios at any time.' FROM games WHERE igdb_id = 70779 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 70779 AND p.igdb_id = 8 ON CONFLICT DO NOTHING;
