INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World War II Combat: Road to Berlin', 'World War II Combat: Road to Berlin, also known as Battlestrike: Secret Weapons, is a budget-priced first-person shooter, developed by Direct Action Games and published by Groove Games. Despite its low-budget price, it has been panned by users and reviewers as having shoddy control, and a rushed, unfinished feel. The game was followed by World War II Combat: Iwo Jima.' FROM games WHERE igdb_id = 6243 ON CONFLICT (game_id, language_code) DO NOTHING;
