INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('zoom-paparazzi-in-action', 344453, '2006-11-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9u3b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc103ee.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zoom: Paparazzi in Action', 'Zoom: Paparazzi in Action is a first-person photography game where players act as paparazzi capturing VIPs in compromising moments across 15 levels. Photos earn money, but bodyguards and rival photographers pose obstacles. Players can temporarily blind pursuers with the camera flash and must reach a set income to complete each mission. Levels are scripted, allowing players to memorize events, with optional humorous interactions throughout.' FROM games WHERE igdb_id = 344453 ON CONFLICT (game_id, language_code) DO NOTHING;
