INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Backyard Sports: Baseball 2007', 'Backyard Baseball 2007 is the fifth iteration of the best selling youth baseball video game of all time and the only kid''s game to hold the coveted Major League Baseball (MLB) and Major League Baseball Players Association (MLBPA) licenses. Backyard Baseball 2007 features a roster full of top MLB pros as kids and includes all 30 MLB teams, uniforms, and logos. In addition, the game''s kid-friendly, non-violent format, and high level of diversity makes it especially popular with parents.' FROM games WHERE igdb_id = 49243 ON CONFLICT (game_id, language_code) DO NOTHING;
