INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-house-of-the-dead-4-special', 134319, '2006-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co49hk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8aal.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The House of the Dead 4: Special', 'The House of the Dead 4 Special is a two-player attraction based on The House of the Dead 4. The game makes use of two 100-inch screens, one in front of the players and another behind, as well as a five-speaker sound system, giving the impression that enemies are attacking from all directions. The seat shakes when zombies attack, and players are blasted with air whenever they take damage. The seat automatically rotates to face the players towards whichever screen zombies are attacking from. The game also features a new addition of a life bar. As the players are hit the life bar diminishes. If the life bar is reduced to zero the game is over. There are no continues. The PlayStation 3 port of The House of the Dead 4 Special is unlocked by completing The House of the Dead 4 for the first time. However, it uses lives rather than the life bar and allow players to continue.
