INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turtix', 'In Turtix, a charming arcade game, a funny little tortoise walks along a fabulously beautiful forest maze and collects gems. On his way, he runs into some angry hippos. They have captured his friends and have them locked up in cages. But Turtix the brave tortoise artfully attacks the invaders with his leg. One, two – and the hippos blow up!' FROM games WHERE igdb_id = 53950 ON CONFLICT (game_id, language_code) DO NOTHING;
