INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Koala Brothers: Outback Adventures', 'You''re never too young for adventure, at least when the Koala Brothers are involved! The Brothers and all their best buddies are waiting for new friends to join them on adventures through the beautiful Australian Outback. Preschoolers can play as all their favorite characters from the Koala Brothers TV show in 10 games packed with between 4 and 20 levels apiece. Kids learn how to handle the easy controls by using graphic-based instructions, so no reading is required! Players can help the brothers find George''s lost mail, play tennis with Archie, hop around as Josie the Kangaroo, help Lolly run her ice cream truck, and more!' FROM games WHERE igdb_id = 49398 ON CONFLICT (game_id, language_code) DO NOTHING;
