INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'David Douillet Judo', 'David Douillet Judo is a judo-focused sports game featuring former Olympic champion David Douillet. Players can compete in single matches, tournaments, and training modes using a roster of international judoka. The gameplay emphasizes throws, holds, and counters with a control scheme built around timing and positional advantage rather than fast-paced combos. Matches follow standard judo rules and scoring (ippon, waza-ari, etc.), and the presentation includes realistic arenas, commentator-style feedback, and career-style progression for improving a fighter’s skills.' FROM games WHERE igdb_id = 57609 ON CONFLICT (game_id, language_code) DO NOTHING;
