INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ōkami', 'Set sometime in classical Japanese history, Ōkami combines several Japanese mythology and folklore to tell the story of how the land was saved from darkness by the Shinto sun goddess named Amaterasu, who took the form of a white wolf with celestial markings covering its fur. It features a distinct sumi-e-inspired cel-shaded visual style and the Celestial Brush, a gesture-system used to perform miracles.' FROM games WHERE igdb_id = 1271 ON CONFLICT (game_id, language_code) DO NOTHING;
