INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('simple-2000-series-vol-105-the-maid-fuku-to-kikanjuu', 43478, '2006-09-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co77di.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scf69x.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 2000 Series Vol. 105: The Maid Fuku to Kikanjuu', 'During the dusk of one day, the girl maid Yuuki, who may act reckless at times, was secretly protecting her future master who was returning home from school. This future master was summoned to his grandfather’s villa and found himself facing a large robot army and a man with a hideous face. Faced with so many enemies, Yuuki had to reveal her identity as the secret bodyguard. What is the identity of this master who is attacked by sexy maids and giant robots? And why is that? The key is linked to a certain secret closely related to him…' FROM games WHERE igdb_id = 43478 ON CONFLICT (game_id, language_code) DO NOTHING;
