INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dirge of Cerberus Lost Episode: Final Fantasy VII', 'Dirge of Cerberus Lost Episode: Final Fantasy VII is a fully-voiced mobile phone game and is a midquel to the original Dirge of Cerberus: Final Fantasy VII third-person shooter game for the PlayStation 2. It featured only a single-player mode, but Multiplayer became available later on. As the infrastructure required to switch episodes was shut down, the ability to fully play the game ended on March 31, 2018.' FROM games WHERE igdb_id = 146428 ON CONFLICT (game_id, language_code) DO NOTHING;
