INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bust-a-Move DS', 'Bust-A-Move DS brings all of the bubble bursting, puzzle fun onto the Nintendo DS. This time Bub and Bob return to center stage as they fling bubbles from the bottom screen to the top in an attempt to match 3 bubbles causing them to pop. With a multiplayer mode allowing 5 people to play via the Nintendo DS'' wireless link, this Bust-A-Move will prove to be the ultimate battle party game.' FROM games WHERE igdb_id = 22572 ON CONFLICT (game_id, language_code) DO NOTHING;
