INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Curious George Learns Phonics', 'Curious George joins the circus in this fun phonics adventure! George is up to his usual antics, sending circus animals flying through the air in dashing acrobatics, laughing at the clowns'' jokes, playing music, and chasing down letters and their sounds. Six games and activities teach children to recognize letters, sounds, and to sound out words as their build basic reading skills.
