INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dirge of Cerberus: Final Fantasy VII', 'Dirge of Cerberus: Final Fantasy VII is an action role-playing third-person shooter. As the first shooter game in the Final Fantasy series, the action is viewed from an over-the-shoulder perspective similar to Resident Evil 4, although players can switch to a first-person perspective if they wish. Defeating enemies yields EXP, and at the end of each stage, the player can either use that EXP to level up, increasing Vincent''s stats, or convert it to Gil (the in-game currency), which can then be used to purchase items and equipment upgrades.' FROM games WHERE igdb_id = 18068 ON CONFLICT (game_id, language_code) DO NOTHING;
