INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy Fables: Chocobo Tales', 'Final Fantasy Fables: Chocobo Tales starts when the Final Fantasy black magician brings a picture book onto the Chocobo farm. This book is actually home to the great devil Bebuzu, and it sucks the entire farm into its pages! Chocobo heads on an adventure with the white and black magicians in order to stop Bebezu from reviving himself to full form.' FROM games WHERE igdb_id = 41830 ON CONFLICT (game_id, language_code) DO NOTHING;
