INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Ebb and Flow of the Tide', 'You have done a horrible thing, so horrible that burial will be denied you, either in soil or sea, neither can there be any hell for you. You wait for some hours, knowing this. Then your friends come for you, and slay you secretly and with ancient rite, and light great tapers, and carry you away.' FROM games WHERE igdb_id = 146196 ON CONFLICT (game_id, language_code) DO NOTHING;
