INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kid Speedy', 'Who''s faster than Kid Speedy? EVERYBODY!! This little fatso is the slowest poke in the bunch. Try not to get dead last while avoiding sweets and insults in this hilarious arcade-style race ''em up.' FROM games WHERE igdb_id = 135867 ON CONFLICT (game_id, language_code) DO NOTHING;
