INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hard Truck Apocalypse: Rise of Clans', 'Hard Truck Apocalypse: Rise of Clans - is an addon to a vehicular Action/RPG set in an alternate future. New heroes and mysteries await you in the vistas of a post-apocalyptic North America. Special customization features, new types of weapons, and hi-tech bosses will immerse you even deeper into the ruthless world of Apocalypse, and your extreme driving skills will serve you well in its new multiplayer mode.' FROM games WHERE igdb_id = 17170 ON CONFLICT (game_id, language_code) DO NOTHING;
