INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('floatpoint', 60139, '2006-09-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/a21w2semwdadslipu4lp.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Floatpoint', 'It is night on this side of the planet. Settled areas are lit: a jagged crescent in the tropics, lining the inland sea. The bright splatter along the top of the curve is Tanhua, as bright from space as New York. The north continent is darker, sprinkled finely with small lights, where the failing climate makes it hard to survive a winter. And the northernmost point, almost lost on the slope of Mt. Cordia, is the original Aleheart Colony, where the first settlers from Earth landed. It is your destination as well. A piece of interactive fiction written by Emily Short.' FROM games WHERE igdb_id = 60139 ON CONFLICT (game_id, language_code) DO NOTHING;
