INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tino''s Fruit Stand', 'The opening of a large, unfriendly MegaMart across the street has put Tino''s family fruit stand in danger of closing! With a little help from Rikki, the fruit-picking monkey, your job is to help him fill orders and keep customers happy. Fill orders correctly to get bonuses, but don''t slow down or let the fruit sit for too long -- that will lead to unhappy shoppers and cost you the family business. Use your power-ups wisely, make the right decisions and you''ll grow more than fruit ... you''ll grow an empire!' FROM games WHERE igdb_id = 327254 ON CONFLICT (game_id, language_code) DO NOTHING;
