INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'James Pond: Codename Robocod', 'Urgent communication: James Pond – Codename: RoboCod has got himself embroiled in some very ''fishy'' business indeed, involving his arch-nemesis, the notorious super-villain…''Dr Maybe''! James Pond launches himself back into battle, to thwart the evil Dr Maybe and his dastardly plans for World domination. With help from his amazing new robotic suit, James Pond must traverse bizarre worlds, jumping, squashing, climbing, stretching and squishing bouncing bears, crazy cadillacs, whirling dervishes, chocolate mountains and not forgetting devious and wacky ''end-of level'' bosses!' FROM games WHERE igdb_id = 51468 ON CONFLICT (game_id, language_code) DO NOTHING;
