INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Densetsu no Starfy 4', 'Densetsu no Starfy 4 is a platforming video game developed by TOSE and published by Nintendo for the Nintendo DS. It is the fourth game in the The Legendary Starfy series, which first started on the Game Boy Advance. As with the other games in the series, Densetsu no Starfy 4 features Starfy as the main character. He is joined by his sister Starpy and his friend Kyorosuke the clam. The three of them help out other undersea creatures and fights numerous villains.' FROM games WHERE igdb_id = 85080 ON CONFLICT (game_id, language_code) DO NOTHING;
