INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Simple 2000 Series Vol. 93: The Unou Drill', 'The Unou Drill: Also released in PSP. Brain training hits the PS2. Based off Kodama Mitsuo''s Right Brain Drill program, the game includes ten drill types as well as an IQ test. The game features 3 different difficulty levels: beginner, intermediate & advanced.' FROM games WHERE igdb_id = 203327 ON CONFLICT (game_id, language_code) DO NOTHING;
