INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shin Gouketsuji Ichizoku: Bonnou no Kaihou', 'Shin Goketsuji Ichizoku: Bonnou Kaihou is the sixth installment in the series and serves as something of a sequel to Matrimelee, although like Power Instinct Legends, it''s also not a proper sequel to the main series, and could be said to be a port or an "update" of Matrimelee. Unlike the other sequels in the series, Bonnou Kaihou is the first one to be made exclusively for a console.' FROM games WHERE igdb_id = 71914 ON CONFLICT (game_id, language_code) DO NOTHING;
