INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tom Clancy''s Rainbow Six: Critical Hour', 'In Tom Clancy''s Rainbow Six Critical Hour, Ubisoft''s Quebec studio blends the finest elements of Tom Clancy''s Rainbow Six series to create the most complete chapter to date. This latest chapter marks the return to the franchise''s roots by reintroducing the deeply strategic and tactical gameplay synonymous with the Rainbow Six name, while incorporating classic in-game elements such as vintage maps and weapons, all rebuilt using today''s technology. Rainbow Six Critical Hour brings a new seven-mission single-player campaign and 18 multiplayer levels.' FROM games WHERE igdb_id = 1852 ON CONFLICT (game_id, language_code) DO NOTHING;
