INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Grievous Getaway', 'Grievous: Getaway is a spinoff video game available exclusively for cellphones. It is published by THQ Wireless like the most part of Star Wars games for mobile telephones. The action takes place during the events of Star Wars: Episode III Revenge of the Sith. The player controls Obi-Wan Kenobi with a goal of eliminating General Grievous. The game has five levels. After completing the game it is possible to play again and choose either character, Obi-Wan Kenobi or Grievous.' FROM games WHERE igdb_id = 75559 ON CONFLICT (game_id, language_code) DO NOTHING;
