INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project Gotham Racing: Mobile', 'Project Gotham Racing Mobile is an adaptation for mobile devices of the Xbox-exclusive Project Gotham Racing series. The game contains eight licensed cars and three cities (London, Paris and San Francisco) with three courses for each location. The available game modes are a solo career and a time trial mode. The solo career consists of several championships with multiple events. By completing them a next championship can be unlocked. There are regular street races against other cars, but also drifting challenges.' FROM games WHERE igdb_id = 221089 ON CONFLICT (game_id, language_code) DO NOTHING;
