INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ds-dengeki-bunko-inukami-feat-animation', 112538, '2006-12-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8ha8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scok5w.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DS Dengeki Bunko: Inukami! feat. Animation', 'Based off of the anime series of the same name, Inukami! is a visual novel with story, artwork, and voice acting to match the slapstick romantic comedy about a boy named Keita and his mischievous companion. In a world where demons with canine features known as Inukami exist, the Inukami tamers must rise up to tame them so that the Inukami shall protect humans with their power. Keita Kawahira, born from a long line of tamers, has only ever successfully managed to partner up with Youko, an uncontrollable yet powerful Inukami.' FROM games WHERE igdb_id = 112538 ON CONFLICT (game_id, language_code) DO NOTHING;
