INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saints Row', 'Saints Row takes place in the fictional city of Stilwater, where the main character is involved in a conflict between four rival gangs. Despite the protagonist''s attempts to remain uninvolved, you are drawn into the conflict and become a member of the Third Street Saints. As the game progresses, you go to war with Los Carnales, the Westside Rollers, and the Vice Kings, gaining status within the gang and taking over the city in the process.' FROM games WHERE igdb_id = 825 ON CONFLICT (game_id, language_code) DO NOTHING;
