INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s American Dragon Jake Long: Rise of the Huntsclan!', 'Jake Long''s most fierce enemy, Dark Dragon, takes Rose, Jake''s love interest, hostage in order to cause Jake''s destruction in Disney''s American Dragon: Jake Long, Attack of the Dark Dragon. When Dark Dragon realizes the evil Huntsman also has an interest in rescuing his hostage, the ultimate duel ensues. Players battle their way through an onslaught of villains that pour in from every direction to save Rose in the process.' FROM games WHERE igdb_id = 49410 ON CONFLICT (game_id, language_code) DO NOTHING;
