INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy VI Advance', 'Final Fantasy VI Advance is more than a simple port of the SNES classic: every aspect of the games has been reviewed and enhanced. Additionally, a host of brand-new elements has been seamlessly merged with the original game, providing unexpected surprises for longtime fans. With new dungeons, new job classes, and other exciting features, both old-school players and newcomers can enjoy this genre-defining FINAL FANTASY title in a portable format.' FROM games WHERE igdb_id = 20655 ON CONFLICT (game_id, language_code) DO NOTHING;
