INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Railfan', 'The first PS3 installment of Ongakukan''s Train Simulator series. It features three different rail lines - JR East''s Chuo Line between Mitaka and Tokyo, the Keihan Electric Railway''s Main Line between Demachiyanagi and Yodoyabashi, and the Chicago Transit Authority''s Brown Line between Fullerton and the Loop. In a first for the series, it features full HD video, as well as the ability to view the train from an external viewpoint. In addition, the game also features a "Densha de Go!" mode emulating the gameplay of that series.' FROM games WHERE igdb_id = 10741 ON CONFLICT (game_id, language_code) DO NOTHING;
