INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney Princess: Royal Adventure', 'Disney Princess: Royal Adventure is an action/adventure game starring your favorite Disney princesses. The game stars an original character named Lily. You''re the young caretaker of a Disney castle, and it''s up to you to find a collection of special crowns that have gone missing. Venture to different areas of the castle and fun places in and around the village, increase your skills and earn enough points to explore several different worlds. During this exploration, you''ll become friends with the Disney Princesses—Jasmine, Cinderella, Belle, Ariel, Snow White and Sleeping Beauty—who will help her on her journey.' FROM games WHERE igdb_id = 49411 ON CONFLICT (game_id, language_code) DO NOTHING;
