INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astérix & Obélix XXL 2: Mission: Las Vegum', 'Astérix & Obélix XXL 2: Mission: Las Vegum is the sequel of Astérix & Obélix XXL, it was released exclusively in Europe due to the lower popularity of the franchise in the United States and Japan. The game stars the French comic book characters Asterix & Obelix and features spoofs to many classic games, in the same fashion that the comics spoof historical characters and make many cultural references.' FROM games WHERE igdb_id = 81480 ON CONFLICT (game_id, language_code) DO NOTHING;
