INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ski Run', 'Ski Run is a classic downhill skiing game where players must navigate through slalom courses as quickly as possible while avoiding obstacles. The gameplay involves precise control to steer between flags and manage speed, requiring a balance of acceleration and braking to complete tracks successfully. It is a fast-paced, winter sports-themed game with several challenging courses to conquer.' FROM games WHERE igdb_id = 324974 ON CONFLICT (game_id, language_code) DO NOTHING;
