INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beetle King', 'In the game the player can explore a magical wood and catch different species of insects, in order to collect data on all the creatures that live in the forest. Another way to obtain the information is to swap the insects with other players. Developed by Warashi; published by D3, 505 GameStreet and Proein. Originally part of the Simple DS Series (Vol. 3), with the alternative japanese title: The Mushitori Oukoku.' FROM games WHERE igdb_id = 18540 ON CONFLICT (game_id, language_code) DO NOTHING;
