INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chosoju Mecha MG', 'Chou Soujuu Mecha MG is a 2006 Nintendo DS mecha action game developed by Sandlot, the studio behind the Earth Defense Force series, and published by Nintendo. It combines the developer''s aptitude for larger-than-life spectacle with one of the most innovative and fun uses of the touch screen in the DS library: in addition to standard movement with the D-Pad, each of the game''s 100+ playable mecha has its own unique "cockpit" controlled with the touch screen.
