INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Top Gun', 'Based on the 80s movie of the same name, this fighter aircraft simulator game offers 10 single-player levels consisting on dogfights, escort missions, target destroy missions, air-to-ground bombings, et cetera. It also features a multiplayer dogfighting mode with up to 4 players. The game plays from a 3rd person point of view of the fighter and is rendered in full 3D.' FROM games WHERE igdb_id = 22913 ON CONFLICT (game_id, language_code) DO NOTHING;
