INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s Kim Possible: What''s the Switch?', 'Kim Possible and her perennial nemesis Shego must grudgingly team up to bring everything back to normal when the minds of Dr. Drakken and Ron Stoppable are switched in this action-packed adventure. It''s now up to Kim and Shego to save the day – together.' FROM games WHERE igdb_id = 8150 ON CONFLICT (game_id, language_code) DO NOTHING;
