INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rule The Beach Volleyball', 'Rule the Beach is a 3D sports simulation game that immerses players in the fast-paced and vibrant world of beach volleyball. Combining realistic visuals with intuitive controls, this game challenges players to master the art of serving, spiking, and volleying while competing in scenic beach settings. Its dynamic gameplay, enhanced by responsive physics, makes for a fun and engaging experience.' FROM games WHERE igdb_id = 324832 ON CONFLICT (game_id, language_code) DO NOTHING;
