INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harlem Globetrotters World Tour', 'For more than 80 years, the "Clown Princes" of the hardwood, have thrilled and delighted worldwide audiences; more than 123,000,000 spectators in 118 countries have witnessed basketball, Harlem Globetrotters style. Now, the Globetrotters, the world''s greatest showmen, take their high-flying athleticism, and audacious antics off the road, and right into your home! DSI Games brings the excitement of Harlem Globetrotters basketball to your favorite video game system. The "can''t miss" ''Trotter''s experience is now a "don''t miss" video game!' FROM games WHERE igdb_id = 6430 ON CONFLICT (game_id, language_code) DO NOTHING;
