INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ford Bold Moves Street Racing', 'This entry in the Ford Racing series sees the racing move onto the streets of Los Angeles, with a unique team racing experience included that puts the player in control of their own Ford Racing three-car team, allowing them to race and also issue commands to team mates to gain tactical and positional advantage. The game showcases 18 fully licensed Ford super cars, from the 1970 Mk1 Capri RS1600, through the Ford GT to the 2007 Shelby GT 500.' FROM games WHERE igdb_id = 43384 ON CONFLICT (game_id, language_code) DO NOTHING;
