INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Secrets of the Ark: A Broken Sword Game', 'Secrets of the Ark: A Broken Sword Game returns to its roots by reintroducing point-and-click-based mouse control next to keyboard control, although still relying on a full 3D engine with fixed camera perspectives. A few puzzles are still action-based, but you are now given more time to act in stressful situations, rather than having to make split-second decisions. Next to the regular puzzles, you need to investigate images, texts and clues in the central manuscript as the story progresses.' FROM games WHERE igdb_id = 1152 ON CONFLICT (game_id, language_code) DO NOTHING;
