INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('who-wants-to-be-a-millionaire-party-edition', 44631, '2006-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ohv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8yv5.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Who Wants to Be a Millionaire: Party Edition', 'It''s time to ask once again, Who Wants to be a Millionaire? This 2006 entry in the series (based on the original UK show) reinvents the series with a new cast of crazy characters, new game modes and a more complete multiplayer game. The challenge, as always, is to answer 15 questions to win a million, using your Life Lines to get yourself through the tough questions if you think you need help. Now you get to choose your on-screen contestant from 16 unique and eager contestants in an authentic Millionaire experience hosted by Chris Tarrant. Up to four people can compete in the multiplayer, which is now bursting with options including a quick fire round, Millionaire party and a play or pass mode in which you can pass difficult questions over to another player. There are 4,000 brand new questions in this version, plus there is an added feature where players who bag the big Millionaire pound prize are given a code they can enter on the game''s website, so they can brag about their feat with other virtual millionaires.' FROM games WHERE igdb_id = 44631 ON CONFLICT (game_id, language_code) DO NOTHING;
