INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Death Worm', 'If you''ve ever secretly harboured a desire to snap up entire elephants in a single bite, Death Worm, more Shai-Hulud than Nibbles, just might be the game for you. Loosely inspired by cryptozoological accounts of the Mongolian Olgoi-Khorkhoi, this game allows the player to be to the Gobi Desert what Jaws was to Amity Island -- a menacing avatar of hunger incarnate, lurking somewhere unseen beneath the surface... waiting to strike!' FROM games WHERE igdb_id = 337201 ON CONFLICT (game_id, language_code) DO NOTHING;
