INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('samurai-warriors-2', 7173, '2006-02-24', 68, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2niw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/vwmgtlco5zwnspthyotl.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Samurai Warriors 2', 'Samurai Warriors 2 is a hack and slash game and the sequel to the original Samurai Warriors. The gameplay of Samurai Warriors 2 builds on the first Samurai Warriors by adding new characters and new features, such as the removal of the traditional range attacks in favor of the addition of two unique special abilities that differ from character to character. A returning element from the original Samurai Warriors is the Survival Mode. In this mode, the player chooses a character and fights through an endless castle. The game also contains a Sugoroku mini-game as an additional feature. Up to four players can participate in this mode, and each player has to choose a character. The game''s goal is to collect the requested amount of gold (depending on the player''s settings).' FROM games WHERE igdb_id = 7173 ON CONFLICT (game_id, language_code) DO NOTHING;
