INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tourist Trophy', 'Tourist Trophy: The Real Riding Simulator is a 2006 motorcycle racing video game. It was designed by Polyphony Digital, the same team behind the popular Gran Turismo auto racing series. Tourist Trophy is one of only four titles for the PlayStation 2 that is capable of 1080i output, another being Gran Turismo 4, the game engine of which is heavily used in Tourist Trophy.
