INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ace-combat-x-skies-of-deception', 14755, '2006-10-24', 50, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2j5g.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc5xk4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ace Combat X: Skies of Deception', 'The first PSP entry of the series and a new game in the franchise, Ace Combat X: Skies of Deception promises everything you''d expect of Namco''s flight simulation series, including detailed jet models, an original storyline told through CG, options for fine tuning your machines, and plenty of real world jets. In Campaign Mode, you play as a pilot in the Gryphus Squadron of the Federal Republic of Aurelia. Defending the invaded country, your mission will take you to the battle-filled skies in order to take down the enemy and restore freedom and peace to their homeland. Campaign mode makes use of the Strategic AI System, where the contents of a mission change based on the strategies that you select. The game also has a multiplayer mode for up to four players. In addition to a last-man standing dog fight mode, you''ll be able to split into teams for cooperative combat.' FROM games WHERE igdb_id = 14755 ON CONFLICT (game_id, language_code) DO NOTHING;
