INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SpellForce 2: Shadow Wars', 'The most beautiful, perfect and deadly of the Dark Races, the Dark Elves, in league with the mysterious Shadows are threatening to overrun the realm of men… Lead the Avatar and his band of heroes in forging new alliances to face the invasion and save the world of Eo ! But soon the Avatar has to discover even more sinister forces at work… Lead your armies in monumental battles and unravel the truth behind this epic story. The burden of ancient blood is heavy; it has fallen on you to carry it...' FROM games WHERE igdb_id = 7033 ON CONFLICT (game_id, language_code) DO NOTHING;
