INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('xuan-yuan-sword-5-a-sword-above-the-clouds-and-the-sentiments-of-the-world-of-shanhai', 78050, '2006-08-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2le3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar55l8.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xuan-Yuan Sword 5: A Sword Above the Clouds and the Sentiments of the World of Shanhai', 'The main character Lu Chengxuan (陸承軒) killed his parents as a result of not being able control his mysterious power, and was about to die in the wilderness as an outcast when he was coincidentally brought to the World of Shanhai through a portal created by Huangfu Muyun (皇甫暮雲), a powerful wielder of sword energy and the avatar of the Xuanyuan Sword, using the Pangu Axe. There, he encounters Xia Rou (夏柔), second empress of the Kingdom of Women. The two traveled around the world, meeting with people from other kingdoms, and set out to accomplish a task given to them by the Elder of the Green Dragon Kingdom, leading to a confrontation with the exiled Princess of Heaven, Qing''er (青兒), who helped the Yellow Emperor, Ji Xuanyuan (姬軒轅), claim the mortal world for humans and was banished due to her newly acquired form causing cataclysmic droughts after expending her power in aiding him in reforging the sword that would later be known as the Xuan Yuan Sword.' FROM games WHERE igdb_id = 78050 ON CONFLICT (game_id, language_code) DO NOTHING;
