INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Freight Tycoon Inc.', 'Freight Tycoon is an economic simulation game which challenges players’ management skills. It puts one into the shoes of an owner of a cargo transportation company. One has to evaluate the profitability of contracts, contact customers, and appoint drivers to deliver goods.' FROM games WHERE igdb_id = 10335 ON CONFLICT (game_id, language_code) DO NOTHING;
