INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soko Banish', 'Help Ardos push all the soulstones onto rune circles in this puzzle game based on the classic Sokoban, but watch out: as in the popular classic, stones can only be pushed and not pulled, so try to avoid unwinnable situations that would surely spell doom as you uncover the right sequence of moves. Open gates, avoid roaming ghosts, and when all challenges are mastered, use the Level Creator to create your own for more fun!' FROM games WHERE igdb_id = 334436 ON CONFLICT (game_id, language_code) DO NOTHING;
