INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Planet Alcatraz', 'Planet Alcatraz is a 3D role playing game with isometric projection. The player travels through the game world and fights against enemies in the real-time mode.Several genres are mixed in this game but despite that fact it isn''t stuck between them and appears to be a classical RPG that is based on a specially developed system.' FROM games WHERE igdb_id = 36385 ON CONFLICT (game_id, language_code) DO NOTHING;
