INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Spyro: A New Beginning', 'The Legend of Spyro: A New Beginning explores the true origins of Spyro as you embark on a dangerous, combat-driven quest that will bring you face to face with the Dark Master''s ultimate creation, Cynder. Experience the true power of the purple dragon as you unleash devastating fury attacks, upgradeable breaths and ground to aerial melee combos in a frenzied battle with hordes of menacing enemies and bone-chilling bosses. It''s an epic and cinematic gameplay experience.' FROM games WHERE igdb_id = 1582 ON CONFLICT (game_id, language_code) DO NOTHING;
