INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Catz', 'Catz is a pet simulation game, where you can adopt and care for your very own kitten. There are 13 different cat breeds to choose from. And players can develop a close bond with their new kitten by feeding, grooming or playing with it. Or they can even spoil their cute kitty with toys and treats brought at the store in game.' FROM games WHERE igdb_id = 81538 ON CONFLICT (game_id, language_code) DO NOTHING;
