INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('spider-man-and-friends-secret-missions', 73001, '2006-06-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/f06pytmuyccerj5uvnyd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scj8qc.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spider-Man & Friends: Secret Missions', 'Join Spider-Man, Spider-Girl and Wolverine on their secret crime-stopping missions! As kids help Spider-Man and his friends, they engage in exciting games and activities that teach key school skills like spelling, counting, problem solving and more. To get these superheroes through four clever learning adventures, kids must master their learning of number sequence, animal names, object identification, problem solving, shape matching, counting and money concepts. Four shorter arcade-style games, focused on letters, pattern matching, classifying and basic math skills, keep kids on target with their learning. Providing hours of thrilling game play, this V. Smile smartridge works with all V. Smile Learning Systems.' FROM games WHERE igdb_id = 73001 ON CONFLICT (game_id, language_code) DO NOTHING;
