INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kirby: Squeak Squad', '"Kirby: Squeak Squad", known in Europe as "Kirby: Mouse Attack" and in Japan as "Kirby of the Stars: Calling on the Dorotche Gang", is a 2006-07 platforming video game developed by HAL Laboratory, Flagship and Natsume, and published by Nintendo for the Nintendo DS handheld video game console. Unlike the previous Nintendo DS title, Kirby: Canvas Curse, Squeak Squad is a traditional platformer which uses the face buttons instead of the touch screen to control Kirby.' FROM games WHERE igdb_id = 3723 ON CONFLICT (game_id, language_code) DO NOTHING;
