INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rayman Raving Rabbids', 'Rayman Raving Rabbids marks the return of the iconic video-game hero, Rayman, in his funniest and zaniest adventure ever. When the world of Rayman is threatened by a devastating invasion of crazed, out-of-control bunnies Rayman must rise up against his furry foes to foil their wicked plans. Utilizing an array of amazing new abilities, and with the help of magical creatures, Rayman must break out all the moves to save his world from these delirious bunnies and their hare-raising antics.' FROM games WHERE igdb_id = 2277 ON CONFLICT (game_id, language_code) DO NOTHING;
