INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('jampack-volume-14', 43314, '2006-05-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4n0h.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jampack: Volume 14', 'This version of JAMPACK VOLUME 14 includes games rated M and is generally for older gamers, although it does includes games rated E and T. JAMPACK VOLUME 14-M includes demo versions of SHADOW OF THE COLOSSUS, RATCHET: Deadlocked, EYETOY: Operation Spy, OKAMI, HITMAN: Bloodmoney, MLB ?06: The Show, LARA CROFT TOMB RAIDER: Legend, BLACK, DRAKENGARD 2, and DRIVER: Parallel Lines. These games cover several genres, including action, racing, sports, and mission-based adventure. Many of the games included in JAMPACK VOLUME 14-M are from series that gamers probably already know about. RATCHET, TOMB RAIDER, DRIVER, and the EYETOY lines are already very popular, and players can get a sneak peak at the newest games in the series on this volume. For players who want to try out games before the buy them, JAMPACK VOLUME 14-M provides the perfect way to check out a game before spending money on it.' FROM games WHERE igdb_id = 43314 ON CONFLICT (game_id, language_code) DO NOTHING;
