INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('naruto-ultimate-ninja-heroes-2-the-phantom-fortress', 19660, '2006-03-30', 66, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1u9j.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/tqluqzguc8cdnythp0ld.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Naruto: Ultimate Ninja Heroes 2 - The Phantom Fortress', 'In Naruto: Ultimate Ninja Heroes 2 - The Phantom Fortress, players take a custom party of four NARUTO characters through over 100 floors of the castle, experiencing fierce one-on-one battles, exciting minigames, and dramatic story twists in an all-out game of survival. Along the way, players will be able to power up each party member in a new character-customization system, equipping abilities and items to gain a decisive edge in battle. Updating the series'' trademark fast-paced combat system, players will be able to pull off acrobatic flying attacks, flashy combo strikes, and unstoppable jutsu skills with ease.' FROM games WHERE igdb_id = 19660 ON CONFLICT (game_id, language_code) DO NOTHING;
