INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yoomurjak''s Ring', 'After his mother’s death, Jonathan Hunt, a young journalist from New York, decides to set off for Hungary for the first time in his life. While in the town of Eger, he discovers a peculiar legend involving an antique book and a doomed journey through time that stranded the writer''s aide in the 16th century.' FROM games WHERE igdb_id = 117716 ON CONFLICT (game_id, language_code) DO NOTHING;
