INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dot-hack-slash-slash-g-dot-u-vol-1-rebirth', 11987, '2006-05-18', 68, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2vtb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/v3khs6u3qizk8zpqgq5l.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '.Hack//G.U. Vol. 1: Rebirth', '.Hack//G.U. simulates a massively multiplayer online role-playing game; players assume the role of a participant in a fictional game called The World. While in The World, the player controls the on-screen player character, Haseo, from a third-person person perspective (with optional first-person mode). The player may control the camera using the game controller''s right analog stick. Within the fictional game, players explore monster-infested fields and dungeons as well as "Root Towns" that are free of combat. They also can "log-off" from the game and return to a computer desktop interface which includes in-game e-mail, news, and message boards, as well as desktop and background music customization options. In Reminisce, an optional card game called "Crimson VS" becomes available. The player may save the game to a memory card both from the desktop and within The World at a Save Shop. After the player completes the game, a Data Flag appears on the save file, which allows the transfer of all aspects of the player character and party members to the next game in the series. This can also be applied to previous games if the player first finished the Reminsce or Redemption.
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 11987 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
