INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu-Gi-Oh! Ultimate Masters: World Championship Tournament 2006', 'Yu-Gi-Oh World Championship Tournament 2006 is a video game based on the Yu-Gi-Oh! franchise. The game play involves the player collecting cards in-game and using them to battle the computer players. Players may also (upon completing the Free Duel mode) battle against Decks which they themselves have designed and saved. This game came with three promotional Yu-Gi-Oh! cards enclosed; they were "Helios - The Primordial Sun", "Helios Duo Megistus", and "Golden Homunculus". These cards were later available in English Blister Packs.' FROM games WHERE igdb_id = 49377 ON CONFLICT (game_id, language_code) DO NOTHING;
