INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Raceway: Drag & Stock Racing', 'Fire up your engines and get ready to tear up the track in the world''s fastest and most dangerous of all motorsports! Launch your funny car, top fueller, or stock car down quarter-mile straights, banked ovals and a host of other wild circuits. With plenty of game modes and insane stunts to master, Raceway: Drag & Stock Racing offers all the high-speed, tyre blistering action.' FROM games WHERE igdb_id = 168316 ON CONFLICT (game_id, language_code) DO NOTHING;
