INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bone: The Great Cow Race', 'It''s spring fair time and The Great Cow Race is about to begin! Play carnival games. Write love poetry. Outsmart a really big bee. Cheat the locals out of their hard-earned eggs. Bang on some pots and pans. Escape from an angry mob. Oh, and dress up like a cow. (Not necessarily in that order.)' FROM games WHERE igdb_id = 10060 ON CONFLICT (game_id, language_code) DO NOTHING;
