INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gintama: Gintoki vs. Hijikata!? Kabukichou Gintama Dai-soudatsusen!!', 'Gintama: Gintoki vs Hijikata!? Kabukichou Gintama Dai Soudatsusen!! is a Japan‑exclusive Nintendo DS action‑adventure game based on the popular Gintama manga and anime series. Developed and published by Banpresto, it features a comedic storyline in which protagonists Gintoki Sakata and Toshiro Hijikata face off in a chaotic competition set in Kabukichou. Players engage in a mix of mini‑games, battles, and interactive story sequences faithful to the series’ humor and characters.' FROM games WHERE igdb_id = 124566 ON CONFLICT (game_id, language_code) DO NOTHING;
