INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F.E.A.R. Extraction Point', 'F.E.A.R. Extraction Point is the first standalone expansion pack for the video game F.E.A.R. A prominent gameplay element new to this game is reflex time, an ability which slows down the game world while still allowing the player to aim and react at normal speeds. This effect is used to simulate the player character''s superhuman reflexes, and is represented by stylized visual effects, such as bullets in flight that cause air distortion or interact with the game''s particle system. Other new features include the ability to bash open doors by using the melee function, as well as blast them open with explosives, and the ability to smash crates, some of which contain supplies.' FROM games WHERE igdb_id = 518 ON CONFLICT (game_id, language_code) DO NOTHING;
