INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frets on Fire', 'Frets on Fire is a free, open-source Finnish music video game created by Unreal Voodoo. Players use the keyboard to play along with markers which appear on screen, with the aim to score points, achieve a high point multiplier, and complete a song. Frets on Fire was the winner of the Assembly 2006 game development competition.
