INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saint Seiya: The Hades', 'Saint Seiya: The Hades is a three-dimensional fighting video game developed by Dimps and published by Bandai for PlayStation 2. A direct sequel to Saint Seiya: The Sanctuary, and developed by the same team, it utilizes the same graphics engine as its predecessor, as well as a significant portion of its storyline, while addressing certain criticisms of gameplay and introducing a new narrative arc.' FROM games WHERE igdb_id = 23113 ON CONFLICT (game_id, language_code) DO NOTHING;
