INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F.E.A.R. Combat', 'F.E.A.R. Combat is a standalone multiplayer component based on F.E.A.R. but released for free less than a year after the original game. F.E.A.R. already had full multiplayer options, but this component allows everyone to join the online battles, without needing to buy the game. It includes 22 multiplayer maps, 10 game modes, all the weapons and updates, and the ability to play user-generated content. You only need to apply for a free CD key. Users of this version can also play against the owners of the original game.' FROM games WHERE igdb_id = 77261 ON CONFLICT (game_id, language_code) DO NOTHING;
