INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Honoo no Takuhaibin', 'Hono no Takuhaibin ("Blazing Express Delivery") is an action delivery game where the player, as experimental enhanced humanoid Jiro, must deliver packages within a time limit, while at the same time defeating or avoiding various enemies. Jiro has access to both a hand cart and a van, which he can switch between at will, though the van cannot enter certain areas. Defeating enemies and completing deliveries will earn Delivery Spirit, which can be used to launch special attacks and boost Jiro''s speed.' FROM games WHERE igdb_id = 140100 ON CONFLICT (game_id, language_code) DO NOTHING;
