INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chess Titans', 'Chess Titans is a chess game with 3D graphics developed by Oberon Games and included in Windows 7. It is a fully animated, photorealistic interactive game with ten difficulty levels. It can be played by two participants, or one player against the computer.' FROM games WHERE igdb_id = 26679 ON CONFLICT (game_id, language_code) DO NOTHING;
