INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dai Senryaku VII: Modern Military Tactics Exceed', 'Dai Senryaku: Exceed is a turn-based strategy game played on an assortment of hex-shaped maps, similar in design to early tabletop and computer war games. Players choose one of eight modern-era countries before waging war in a series of 25 missions, each offering multiple objectives and win conditions. The game includes Free Play, Mission, and Campaign modes, over 400 units and 100 maps in total, and multiple tutorials to help new generals learn the play mechanics.' FROM games WHERE igdb_id = 43596 ON CONFLICT (game_id, language_code) DO NOTHING;
