INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MVP 06: NCAA Baseball', 'The makers of the highest-rated and top-selling baseball game of the past three years have created a completely new baseball experience: MVP 06 NCAA Baseball. Inspired by the spirit and emotion of collegiate athletics, MVP 06 NCAA Baseball is the first-ever college baseball game, changing the way baseball video games are played with the all-new Load and Fire Batting system. With the aid of the right analog stick and all-new swing types, take complete control of your swing - protect the plate with the mentality of a contact hitter or take aim at the cheap seats by swinging like a slugger. Featuring the top universities and conferences, battle your way to Omaha and enjoy the game like a kid again with MVP 06 NCAA Baseball.' FROM games WHERE igdb_id = 5937 ON CONFLICT (game_id, language_code) DO NOTHING;
