INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Chosen: Well of Souls', 'The Chosen: Well Of Souls is an action role-playing game (RPG) in a dark period of the 19th century. The story revolves around 3 characters: Frater Simon, Elena, and Tong Wong (respectively mage, thief, and warrior), who are members of the Mystery Guards Fraternities, organizations devoted to exterminating demons and dark forces. They are now after an immortal sorcerer, Marcus Dominus Ingens, who commands armies of demons, summoned with the souls of alchemists and is bent on destroying God''s Envoy, a powerful being who appears every 200 years.' FROM games WHERE igdb_id = 21228 ON CONFLICT (game_id, language_code) DO NOTHING;
