INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PokerTH', 'PokerTH is an open-source Texas hold ''em simulator that runs on Windows, Mac OS X, Linux, and Android. PokerTH is written in C++ using the Qt framework and allows for up to ten human players, with computer-controlled players filling in if there are not enough humans. Players can also play against other PokerTH users online.' FROM games WHERE igdb_id = 250379 ON CONFLICT (game_id, language_code) DO NOTHING;
