INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PachiPara 13: Super Umi to Pachipro Fuuunroku', 'PachPara 13 is one of the many titles in Irem''s long-running pachinko simulation series. It features faithful 3D recreations of two pachinko machines made by Sanyo Bussan: CR Super Umi Monogatari M55W and CR Super Umi Monogatari M55X. There are two modes available: Tsūjō (Normal) mode allows the player to modify a wide range of settings for each machine, while Jissen (Battle) mode challenges the player to win as many balls as possible on the default settings with a limited starting pool and time limit. There is also a View mode where the various animations that play on the in-game display can be freely viewed.' FROM games WHERE igdb_id = 77996 ON CONFLICT (game_id, language_code) DO NOTHING;
