INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darkest Fear 3: Nightmare', 'Nightmare is the third and final game in the Darkest Fear trilogy and features two playable characters instead of just one in the previous games, Thomas Warden and his daughter Helen with cooperative gameplay. The game mechanics remain the same: survival horror mainly based on light sources and lots of puzzle solving, all shown from an overhead view. The game has a hidden Pong-like mini-game, 15 different endings, and Helen can obtain three unique monster abilities.' FROM games WHERE igdb_id = 223006 ON CONFLICT (game_id, language_code) DO NOTHING;
