INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Football Manager Quiz', 'Although it''s based on the planet''s best football management game on PC, console and PSP, Football Manager Quiz takes a different spin on the genre. Instead of taking your team to the top of the Premier League with cunning tactics and wheeler-dealer transfer skills, success is based entirely on your footie-trivia knowledge.' FROM games WHERE igdb_id = 318991 ON CONFLICT (game_id, language_code) DO NOTHING;
