INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mini Golf Mayhem', 'Tee off in the crazy world of Mini Golf Mayhem! Now you and up to 8 of your friends can play the kookiest, most fun-filled mini golf game created! Grab your club and putt your way through more than 50 unique holes spread over 5 zany courses! You''ll enjoy gorgeous 3D graphics and an ultra-realistic physics engine that guarantees this to be the most original mini golf game around!' FROM games WHERE igdb_id = 129500 ON CONFLICT (game_id, language_code) DO NOTHING;
