INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saru Ga Daisuki', 'Saru Ga Daisuki is a platform game where the player controls a ninja monkey, out to save his girlfriend from an evil doctor. The monkey can run around, jump, and cling to walls and ceilings freely; it also has a weapon in the form of a yo-yo with which it can destroy green blocks and flip switches.' FROM games WHERE igdb_id = 199197 ON CONFLICT (game_id, language_code) DO NOTHING;
