INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blood-over-', 'While fighting demons during an outbreak of monsters and supernatural forces, Shou, a demon hunter who wields the power the absorb demon''s souls, confronts a shinigami who overpowered Shou and stolen her soul. Aided by house maid, the Gatling gun-wielding Akari, they must track down the shinigami to reclaim Shou''s human soul before her demonic blood lust consumes her.' FROM games WHERE igdb_id = 93069 ON CONFLICT (game_id, language_code) DO NOTHING;
