INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dance Dance Revolution Ultramix 4', 'The hottest revolution and bestselling video game in the music game category delivers its best dance performance yet on the Xbox with Dance Dance Revolution Ultramix 4. Jam-packed with new features, modes, music and gameplay, ULTRAMIX4 offers incredible content for casual, beginner and advanced dancers. For first time players, Dance Dance Revolution ULTRAMIX4 is the perfect introductory game in the series with new tutorials and super-easy levels to make anyone a dancing machine.' FROM games WHERE igdb_id = 5802 ON CONFLICT (game_id, language_code) DO NOTHING;
