INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dino King Battle: Taiko Kara no Hyouryuusha', 'Dino King Battle: Taiko Kara no Hyuuryuusha is a TCG game for the Nintendo DS system developed by Skonec Entertainment and published by Taito Corporation. It was released exclusively in Japan on August 24 2006, and it was a port of a Korean arcade game from 2005 made by Netdol and D-Gate known as Gongyong Wang (공룡왕 lit. Dinosaur King. It was known as King of Jurassic in Southeast Asian countries and in Taiwan, China and Hong Kong). Despite Gongyong Wang being released by Taito in some Asian countries, Dino King Battle: Taiko Kara no Hyuuryuusha remained as a Japan-exclusive game.' FROM games WHERE igdb_id = 269741 ON CONFLICT (game_id, language_code) DO NOTHING;
