INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aria: The Natural ~Tooi Yume no Mirage~', 'Akari Mizunashi continues her job as a gondolier along with her friends from the other two rival companies, Aika and Alice. As they continue their training to become Undines, they continue to meet new people and partake on mysterious adventures, all in the quiet, scenic, and peaceful city of Neo Venezia.' FROM games WHERE igdb_id = 43407 ON CONFLICT (game_id, language_code) DO NOTHING;
