INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PQ: Practical Intelligence Quotient', 'Based upon psychological research, your PQ score will be determined by how quickly and effectively you solve each life-like situation. Test your wits, bend your brain, and match wits with the minds of users worldwide. A 3D puzzle game that tests players problem solving skills, PQ uses the PSP® system''s Infrastructure Mode and allows players to post their PQ score on the worldwide ranking site to see how they rank against other players around the world.' FROM games WHERE igdb_id = 46019 ON CONFLICT (game_id, language_code) DO NOTHING;
