INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Four-Play', 'Four-Play is a classic board game that has finally made its way to the Atari 2600. Four-Play has easy to learn rules, but don''t expect to become a master as easily! Red and Blue take turns dropping marbles into an upright board. The first player to align four marbles horizontally, vertically, or diagonally wins! Pit your wits against the computer A.I. at four difficulty levels, or play against a friend in two-player mode.' FROM games WHERE igdb_id = 91492 ON CONFLICT (game_id, language_code) DO NOTHING;
