INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('guilty-gear-dust-strikers', 9149, '2006-05-25', 45, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co735t.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/c7n6frfgr0wdmtiifqhm.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guilty Gear Dust Strikers', 'The no holds barred, sci-fi fighting franchise is reborn on the Nintendo DS. Guilty Gear Dust Strikers features all 21 Guilty Gear characters from previous versions (including SolBadbuy, Potemkin, May, Dizzy and others) in a battle that takes place on multiple levels across both DS screens. Navigate different types of floors and traps as you battle against the computer or via wireless multi-player connections. 6 modes of play including Arcade, Story, VS Battle and mini games. Customize the Robo-Ky character with various move sets in the Robo-Ky factory mode. Battle your friends in 4-player wireless versus matches where the last person standing moves on. Master 10 mini-games like Billiards, Arm-Wrestling and Sword Practice that unlock more Robo-Ky moves. Beware of poison, fire, thunder and bomb traps set to damage unaware opponents. Special moves like Psych Burst, Dust Attack and Roman Cancel all return in Guilty Gear Dust Strikers.' FROM games WHERE igdb_id = 9149 ON CONFLICT (game_id, language_code) DO NOTHING;
