INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bibi und Tina: 5 Sterne für den Martinshof', 'Based on the popular German children’s audio play series Bibi & Tina, this game is about making Tina’s home, the horse farm called Martinshof, the best vacation place for horse-loving children. By playing mini-games you achieve your goal: renovating the farm, decorating the rooms, designing posters, planning a riding tour and more. The better your performances in these replayable mini-games are, the more points you get to earn 5 stars.' FROM games WHERE igdb_id = 218266 ON CONFLICT (game_id, language_code) DO NOTHING;
