INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Foosball Champ 3D', 'Foosball Champ 3D is a simulation of the game of Foosball. Play against three different levels of AI, or play against a friend over the network. The table, figures, and team colors are customizable. The controls are customizable (important for a foosball game) with optional assist modes. Winning conditions are also changeable, and can be set to a time limit or number of goals.' FROM games WHERE igdb_id = 146415 ON CONFLICT (game_id, language_code) DO NOTHING;
