INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultimate Mahjongg 20', 'Get the most fun out of Mahjongg with the most layouts, the most tile sets & the most ways to play! Test your skill and try your patience with fun 3D Mahjongg layouts, or create your own with the Layout Editor! Select from hundreds of eye-popping tile sets -- for added fun, you can even create your own tile sets! Choose from 2,500+ breathtaking backgrounds, or import your favorite family or vacation photos for an infinite number of background choices!.' FROM games WHERE igdb_id = 53942 ON CONFLICT (game_id, language_code) DO NOTHING;
