INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Novadrome', 'Blast, smash and crash your way to victory as you fight friends and foes alike for survival in the combat-driving, multi-player arenas of Novadrome! Choose from frantic 8-player gameplay or single-player combat driving action set in a far-out alien world. Play against your friends and blow them up for only 800 points! 24 distinct off-road buggies to choose from, 15 arenas of non-stop action, and 6 event types for pure Novadrome fun!' FROM games WHERE igdb_id = 21941 ON CONFLICT (game_id, language_code) DO NOTHING;
