INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cougar''s Quest for Freedom', 'CQFF is the first game I made with AGS. I made the game for MAGS, a monthly AGS adventure game creation competition. The guideline was to make a game with animals as characters, so I decided that my cat attempting to escape from the house would make a good little quick game. I actually spent WAY more time than I expected on it, but I''m pretty happy with the end result.' FROM games WHERE igdb_id = 166853 ON CONFLICT (game_id, language_code) DO NOTHING;
