INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Soujiki', 'Touhou Soujiki is a fan-made Touhou Project challenging vertical-scrolling danmaku shooter. It is unique in the fact that you shoot no bullets, and are forced to traverse either part of or the whole screen, and travel over every tile in almost every stage. Bombs are gained not through items, but rather by grazing and sweeping more tiles. Point items are gained only through bombs.' FROM games WHERE igdb_id = 142060 ON CONFLICT (game_id, language_code) DO NOTHING;
