INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Donkey Kong Banana Kingdom', 'Donkey Kong Banana Kingdom is a Japan-only Donkey Kong franchise game. It is a sequel to Donkey Kong Jungle Beat and Donkey Kong: Jungle Fever. It is a 6 player coin pusher medal machine manufactured by Capcom. It includes a number of mini games featuring Donkey Kong. Other than that, not much information about this game is known, and its relation to the Banana Kingdom is unknown. Donkey Kong: Banana Kingdom involves Sensei Kong and a few other Kongs that debuted in the previous games. An arcade game developed by Capcom in collaboration with Nintendo based on the Donkey Kong franchise, which was only ever released in Japan.' FROM games WHERE igdb_id = 59215 ON CONFLICT (game_id, language_code) DO NOTHING;
