INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Naked War', 'Naked War is a light hearted, turn-based, battle game for two players, played on Windows PCs over email. Its a Community Messaging Game. Each game is played on an island where two squads of up to four soldiers battle each other for supremacy. The player takes the role of a military officer, issuing strategic commandings to his/her squad, then watching the resulting battle unfold.' FROM games WHERE igdb_id = 28962 ON CONFLICT (game_id, language_code) DO NOTHING;
