INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bit Generations: Coloris', 'Coloris is a Game Boy Advance video game that is simply just a basic puzzle video game. In the game, you''ll be required to place three similarly colored tiles next to each other in order to rid of them. However, unlike most games like this, you don''t swap the tiles but rather start to change the color of the tile by pressing on them with the cursor.' FROM games WHERE igdb_id = 79016 ON CONFLICT (game_id, language_code) DO NOTHING;
