INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dobrynya Nikitich i Zmey Gorynych', 'Based on the animated film of the same name Dobrynya Nikitich i Zmey Gorynych is the second game in Bogatyrs series. The game is a classic point-and-click adventure with a few brief acrcade-style episodes that looks and plays very similar to Alyosha Popovich i Tugarin Zmej. Prince Vladimir''s niece Zabava was kidnapped and the trail leads to Zmey Gorynych, the three-headed dragon. Dobrynya Nikitich and his apprentice Yelisey come to the rescue to discover a plot of treachery along the way. The player controls either of two heroes that are switched automatically depending on the situation.' FROM games WHERE igdb_id = 188212 ON CONFLICT (game_id, language_code) DO NOTHING;
