INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Magic Farm', 'While you''re away at school studying horticulture, you receive terrible news -your beloved parents are missing! Back at the homestead, put all your newly acquired knowledge to use in order to raise money to find them. Grow beautiful flowers and arrange them into bouquets to sell for premium prices, but watch out for pests. Find new seeds to nurture even more exotic flora as you traverse this gorgeous world!' FROM games WHERE igdb_id = 176016 ON CONFLICT (game_id, language_code) DO NOTHING;
