INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Illegal Communication', 'Illegal Communication is a short, surreal action game with minimalistic, vector-like graphics. The player controls a "defence orb", deployed in order to destroy an "illegal communication". The controls and rules aren''t explained in the game, and the player is challenged to find everything out on his own.' FROM games WHERE igdb_id = 199084 ON CONFLICT (game_id, language_code) DO NOTHING;
