INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gods: Lands of Infinity', 'Gods: Lands of Infinity is a blend of adventure and action in a turn-based setting. There is an array of missions and NPCs who players can add to their team. Players must fight, gain experience, level and acquire new skills. The game is played out in the first-person perspective, until gamers enter a battle encounter, at which point the game goes into third-person turn-based mode.' FROM games WHERE igdb_id = 69674 ON CONFLICT (game_id, language_code) DO NOTHING;
