INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales of Mobile: Tales of Wahrheit', 'Tales of Wahrheit is a role-playing game similar to Tales of Breaker and Tales of Commons. "Wahrheit" is the German word for "truth". The main characters of the game are 16-year-old Seltz Vakstrum and Vila Czarheit, and they are accompanied by Blitz Vinte, Kalulu von Atmigar, Gamut, and Ray Sonne. A theme song by JAMOSA feat. CORN HEAD called Ienaiyo accompanies the game. This is the last of the three Tales mobile titles with their own self-contained stories and characters.' FROM games WHERE igdb_id = 294610 ON CONFLICT (game_id, language_code) DO NOTHING;
