INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiger Woods PGA Tour 2007', 'Take the road to the PGA Championship with Tiger Woods PGA Tour 07. At home or on the go, challenge the world''s top golfers in all-new PGA Tour Mode, featuring training sessions, practice, and The FedEx Cup, the new PGA Tour championship playoff system. Hone your skills in the all-new Shooting Gallery, then play as or against 11 players, including John Daly, on 12 championship courses.' FROM games WHERE igdb_id = 42805 ON CONFLICT (game_id, language_code) DO NOTHING;
