INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Field Commander', 'From Sony Online Entertainment, the makers of Untold Legends on PSP, Field Commander is a turn-based strategy game for the portable system. Use any of the game''s 15 military units to conquer the opposing army, and deploy your field of 11 officers to lead the battle. Field Commander features 30 single-player battles, plus offers a level designer function and multiplayer head-to-head over ad-hoc and internet play.' FROM games WHERE igdb_id = 42873 ON CONFLICT (game_id, language_code) DO NOTHING;
