INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Roswell UFO Attack', 'Unravel the alien conspiracy! The small nation of Voronezh, once part of the former Soviet Union, has come to possess alien spaceships and weapons, and is secretly using these to build a military campaign against Russia. Moscow must send in a very special fighter pilot—an experiment with capabilities far beyond the normal human range. You are Pilot "XP238," and you must find your enemy’s weakness and steal the alien technology.' FROM games WHERE igdb_id = 8358 ON CONFLICT (game_id, language_code) DO NOTHING;
