INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NFL Street 3', 'With NFL Street 3 you can play your style of football both on the ground and in the air in this newest iteration of the popular NFL Street franchise. Show off your style and boost your score by performing stunning aerial moves, jumping into the air and collecting special items and game modifiers that hover above the playing field. You will also have the ability to control your Gamebreaker and pull off new Power moves that are available to both the offense and the defense.' FROM games WHERE igdb_id = 8266 ON CONFLICT (game_id, language_code) DO NOTHING;
