INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Luftwaffe Airstrike', 'The time is World War II. The Third Reich has cloned thousands of zombie pilots in secret labs as part of their plan for world domination. If they are not stopped, the Allied airforce will be wiped out and the Luftwaffe''s strategic control of the skies will be absolute. But the Allied command has created a secret counter-operation codenamed ''Sky Fire'' and called upon their top three pilots to meet the Nazi threat. Their mission, and yours, is to destroy the enemy at any cost.' FROM games WHERE igdb_id = 146433 ON CONFLICT (game_id, language_code) DO NOTHING;
