INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Burning Fists: Force Striker', 'Burning Fist (also known as Force Striker in its early alpha build) is a cancelled fighting game that was in development in 1994 by Sega of Japan for the Mega CD. As we can read at Sega Base, both the Force Striker alpha and the Burning Fists beta were leaked rom a former SoJ employee and sold on eBay some years ago. Burning Fist was never officially released, but in 2006 those alpha / beta builds were re-sold to Good Deal Games.' FROM games WHERE igdb_id = 46403 ON CONFLICT (game_id, language_code) DO NOTHING;
