INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trail Raider', 'Trail Raider is a promotional flash game for Tomb Raider and Chrysler/Jeep, coinciding with the release of Tomb Raider: Legend. The game utilizes an easy to play adventure game that demonstrate new Jeep four wheel drive technologies in the new ''06 models as well as leveraging the Tomb Raider and Lara Croft brand. The game has three levels. On level 1 the player drives Jeep Wrangler, Level 2 has Jeep Commander, and on level 3 the game lets the player choose the Jeep vehicles. The goal of the game is to finish the levels as fast as possible.' FROM games WHERE igdb_id = 165186 ON CONFLICT (game_id, language_code) DO NOTHING;
