INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puzzle Challenge: Crosswords & More!', 'Puzzle Challenge: Crosswords & More! offers more than 200 hours of gameplay, ranging from easy to difficult standard crosswords, codebreakers that require the player to determine number matches assigned to each letter of the alphabet, puzzles with cryptic clues, diamond shaped puzzles and backwards puzzles where the player fills in their own black squares. Word searches come in standard or themed versions. Profiles can be set for multiple players so that the entire household can use the software. Exclusive to the PSP system version is a two-player game sharing mode that enables two people on separate handheld consoles to play the game via wireless connection using one disc.' FROM games WHERE igdb_id = 44699 ON CONFLICT (game_id, language_code) DO NOTHING;
