INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kenny''s Adventure: In search of family treasures', 'A band of pirates has stolen the Crystal of Destiny. Worse yet, they''ve broken this relic and have strewn in all over the world. As Kenny it''s up to you to collect the fragments of this long lost family heirloom and reunite them. Naturally, if you happen to find some other treasure along the way it sure wouldn''t hurt.' FROM games WHERE igdb_id = 70352 ON CONFLICT (game_id, language_code) DO NOTHING;
