INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Veck', 'Veck is an immensely fast-paced romp through fiften one-minute-long levels, with massive firepower upgrades every minute - you’re firing 1,575 bullets every second in the fifteenth minute! The upgrades aren’t enough to defeat the toughest enemies, however - you’ll have to duck and dodge some very taxing baddies if you want to get a high score.' FROM games WHERE igdb_id = 71208 ON CONFLICT (game_id, language_code) DO NOTHING;
