INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kamaitachi no Yoru Triple: Mikazukishima Jiken no Shinsou', 'Toru Yajima and Mari Kobayashi return to Mikazuki Island. They stay at the cursed "prison" mansion once again and are joined by a cast of characters including Yosuke Mikimoto, Toshio Kubota, Seiichi Kayama, Keiko Kitano and a woman named Haruko. A murder mystery is afoot where gamers go through the story from the viewpoint of four characters who look at events from different perspectives (both literally and figuratively) in order to deduce the identity of the killer.' FROM games WHERE igdb_id = 64839 ON CONFLICT (game_id, language_code) DO NOTHING;
