INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Slyder', 'Direct an adorable ball named Slyder through a thrilling set of mazes. You guessed it... the blue lovable hero is back with an all-new addictive adventure containing level-altering items, 9 unique characters, and hilarious animations. This new slippery version also comes with 280+ challenging levels and an easy-to-use level editor. Play the levels at your own pace with level-skipping ability. Let the stress fall away as you slide into this fun adventure!' FROM games WHERE igdb_id = 132726 ON CONFLICT (game_id, language_code) DO NOTHING;
