INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Noddy: A Day in Toyland', 'Noddy wakes up in his colourful building block house and starts his day with a smile. Driving around Toyland he meets several friends who are in need of help -and Noddy is always willing to lend a hand. Play and interact with Noddy and other favourite characters from Toyland including Big Ears, Mr. Sparks, Miss Pink Cat, Tessie Bear, Dinah Doll, Martha Monkey and Mr. Wobbly Man. Visit Big Ears or help Mr Sparks locate his tools or find Tessie Bear''s dog and help her make delicious strawberry ice cream.' FROM games WHERE igdb_id = 49388 ON CONFLICT (game_id, language_code) DO NOTHING;
