INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic Utopia', 'Sonic Utopia is a 2D Sonic fangame created by BlueFrenzy in 2006 made with Klik &Play. It is most well known for its original zone Panic City, which has since made appearences in Ring Racers and Sonic Legends (Two other famous Sonic Fangames). It is not to be confused with Sonic Utopia (2020) by Mr. Lange.' FROM games WHERE igdb_id = 305281 ON CONFLICT (game_id, language_code) DO NOTHING;
