INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moto Racer 3: Gold Edition', 'The arcade motorbike racer returns! Lock up your moped, and get ready for some high speed racing with the return of the great Moto Racer series. At over 150 mph on international circuits or getting some great air off a dirt jump, you''ve got all the different two wheeled motor sports you can think of to up your adrenaline, all mixed for a unique blend of arcade racing. And if you''re a motorbike connoisseur you can manage your bikes and parts to get the most out of your set-up. Unleash your speed dream!' FROM games WHERE igdb_id = 46701 ON CONFLICT (game_id, language_code) DO NOTHING;
