INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'QBeez 2', 'The adorable stars of one of the most addictive puzzle games around are back! And this time, they''ve brought a few friends! Join the colorful QBeez on Q''s Quest where you''ll be introduced to twelve all-new puzzle elements, including explosive bombs, buzzing bees, chomping sharks and more. Challenge your matching skills in Classic Mode or bend your brain in Puzzle mode. Even create your own QBeez puzzles in the easy-to-use Puzzle Maker. QBeez together - again!' FROM games WHERE igdb_id = 304318 ON CONFLICT (game_id, language_code) DO NOTHING;
