INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Terrawars: NY Invasion', 'Terrawars: NY Invasion is a budget-priced first-person shooter that takes place in an alien-infested New York City. You play as John Armstrong, a medical student that''s been drafted into the Army National Guard to fight the aliens. The game plays in standard first-person shooter fashion: Move through the level, kill all the aliens, and try not to get killed by them. In some levels, you''ll meet allies who will fight the aliens alongside you.' FROM games WHERE igdb_id = 70467 ON CONFLICT (game_id, language_code) DO NOTHING;
