INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ruff Trigger: The Vanocore Conspiracy', 'Ruff Trigger: The Vanocore Conspiracy is a 2006 action-platform video game developed by Playstos Entertainment and published by Natsume in North America and by ZOO Digital Publishing in Europe for the PlayStation 2. The game was released in North America on June 28, 2006 and in Europe on August 25, 2006.' FROM games WHERE igdb_id = 20539 ON CONFLICT (game_id, language_code) DO NOTHING;
