INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Pipes', 'Oh no! A blackout has hit the city and as the only electrician in town, it''s up to you to restore power. Connect the contacts to create spectacular electrical discharges and give the city a jolt of juice. The longer and more complex your circuit, the bigger the surge and the higher your score!' FROM games WHERE igdb_id = 146913 ON CONFLICT (game_id, language_code) DO NOTHING;
