INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yoshi''s Egg Toss', 'Yoshi''s Egg Toss was a Nintendo-published online Flash advergame promoting the release of Yoshi''s Island DS on the Nintendo DS. It could be played either at the official microsite of Yoshi''s Island DS or at the Nintendo Arcade, a section on nintendo.com that contained promotional web games.' FROM games WHERE igdb_id = 231529 ON CONFLICT (game_id, language_code) DO NOTHING;
