INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Daemon Summoner', 'With his infant son brutally murdered, and wife Emily reborn as a Vampire, James Farrington-Higgs has himself become a creature of the darkness. Now he must strike back against the evil forces, desperately prowling the streets of London in search of his vampire bride. His journey will uncover a horrific conspiracy as he battles to save his wife and prevent the completion of a demonic ritual held deep within the catacombs of an ancient monastery.' FROM games WHERE igdb_id = 44628 ON CONFLICT (game_id, language_code) DO NOTHING;
