INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pocket Racers', 'Pocket Racers features miniaturised cars whizzing around a series of everyday environments. The player is cast as a spoilt teenager at a party, who is transformed into a toy car by of a vengeful demon. What follows is a frenetic race for survival as the ''Nemesis'' demon sets a series of increasingly hard challenges within the fully interactive and destroyable!' FROM games WHERE igdb_id = 203188 ON CONFLICT (game_id, language_code) DO NOTHING;
