INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blast Factor', 'Blast Factor is a physics-based action game which takes players into a fierce microbiological arena to guide a nano-machine against viral swarms. Proceed from specimen to specimen, waging microscopic war against an array of deadly viruses. Tilt the SIXAXIS controller to send ripples through the arena that shove enemies into groups, and then blast ‘em into catastrophic chain explosions for big points! Immersive high adrenaline arcade action in full HD at 1080p.' FROM games WHERE igdb_id = 23105 ON CONFLICT (game_id, language_code) DO NOTHING;
