INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'N-Ball', 'N-Ball is a crazy physics-based 2D platform. In this game you control N-Ball, a kind of ever burning plasma ball, through 40 levels full of platforms, ropes, swings, vehicles and lots of other weird structures. And with the level editor (available with the full version) you can also create your own levels or play those made by your friends! A bit tricky at first but lots of fun once you get the hang of it!' FROM games WHERE igdb_id = 67084 ON CONFLICT (game_id, language_code) DO NOTHING;
