INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aquaball', 'Experience a magnificent underwater world of sunken ships and pirate booty in Aquaball, a visually stimulating and addictive new Arkanoid adventure. As you dive into 140 exotic levels, you''ll be challenged to keep one or more balls in play as you shatter brilliantly animated seashells, hit daggers that slice across the screen and enter portals that transport your ball into protected treasure troves.' FROM games WHERE igdb_id = 312640 ON CONFLICT (game_id, language_code) DO NOTHING;
