INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s American Dragon: Jake Long - Attack of the Dark Dragon', 'Attack of the Dark Dragon for the Nintendo DS lets players take control of Jake, who must punch and kick his way through an onslaught of villains to save Rose from the Dark Dragon. American Dragon—Attack of the Dark Dragon boasts five distinct worlds with more than 20 levels. When Jake transforms into the American Dragon, players can release dragon fire, perform jump attacks, whip with a tail swipe and take flight in 3D with up to four friends in wireless mode.' FROM games WHERE igdb_id = 8464 ON CONFLICT (game_id, language_code) DO NOTHING;
