INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('city-life', 28979, '2006-05-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/n6tkbwg32m4usqvvq0bz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sca3xi.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'City Life', 'City Life is another take on the old city building genre. Like SimCity, it requires you to build a functioning metropolis. However, City Life also adds a social aspect to the game. Your city is populated by citizens of six different economic classifications, from "Have-Nots" to "Blue Collars" to "Elites". Each social stratus has its own needs, some of which conflict with the needs of the other social classes. So you have to balance the social needs of your citizens as well as the zoning needs of your city. You have to adapt your strategies according to the citizens'' needs, who communicate with you.
