INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elastic Soccer', 'Elastic Soccer is a classic soccer-themed flash game with a twist. In this game, the players cannot move except for the goal keeper. The ball on the hand, gets attracted to the nearest player. Players must then shoot the ball like a rubber band and try to get a good angle for a shot. Take control of the goal keeper by pressing and holding down the Shift Key. The goal of the game is to outscore your opponent before the match is over.' FROM games WHERE igdb_id = 323950 ON CONFLICT (game_id, language_code) DO NOTHING;
