INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cabbage Patch Kids: The Patch Puppy Rescue', 'The Cabbage Patch Kids recently rescued puppies and are holding a lunch in town square to celebrate their new additions. While the puppies nap in the Babyland Playroom, the kids head to lunch in the square. Upon their return they find that they puppies have wrangled their way loose and escaped! You''ll track them down in the park, in town, even at a car wash! After you find everyone''s puppies, you''ll encounter one puppy without a home...it just so happens it''s the perfect fit for you!' FROM games WHERE igdb_id = 49363 ON CONFLICT (game_id, language_code) DO NOTHING;
