INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Memories of Mana', 'Memories Of Mana is a fangame created using RPG Maker XP by Moghunter. The game features graphics from Square Enix''s Seiken Densetsu 3 series. This was not only Moghunter''s first but perhaps also his only completed game. After finishing Memories Of Mana, he bid farewell to the maker community, choosing to dedicate himself to other programming endeavors.' FROM games WHERE igdb_id = 283372 ON CONFLICT (game_id, language_code) DO NOTHING;
