INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mainichi Issho', 'Mainichi Issho is a Japanese video game developed by BeXide and published by Sony Computer Entertainment for the PlayStation 3 starring the PlayStation mascot Toro Inoue. It ran from November 11, 2006 to 2009 and was replaced by Weekly Toro Station. There was also a version for the PlayStation Portable called Mainichi Issho Portable. Trial versions of both the PSP and PS3 versions can be found on the original Japanese version of Toro! Let''s Party!.
