INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney''s The Little Mermaid: Ariel''s Majestic Journey', 'Take an exciting journey with Ariel, the beautiful and curious mermaid, and help make her dream come true! As kids explore the enchanting world under the sea, they engage in challenging games and activities that teach key school skills like vocabulary, counting, problem solving and more. Eight clever learning adventures take Ariel through her secret grotto, into a sunken boat and on a mission to save her trapped friends and her father King Triton!' FROM games WHERE igdb_id = 258692 ON CONFLICT (game_id, language_code) DO NOTHING;
