INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Play TV Football', 'This interactive football video game system plugs directly into a television and translates players'' running movements to control game play, allowing two players to compete against each other or play on the same team. Players stand on the control pad and step on left and right direction indicators to avoid tacklers and collect power-ups such as invincibility, earthquake, speed, and more. The football-shaped game paddle controls play selection, executes hand-offs for running plays, and allows you to throw passes. Requires four AA batteries. Ages 8 and up. 18 1/2" L x 14 1/2" W. (4 lbs.)' FROM games WHERE igdb_id = 246181 ON CONFLICT (game_id, language_code) DO NOTHING;
