INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Touhou Soccer Moushuuden', 'Touhou Soccer Moushuuden is a Touhou Project fangame that''s a stand-alone expansion to Touhou Soccer that adds various new features to the original game. It includes the original game''s Main Scenario mode, and adds sub-scenarios for a number of characters in which you can unlock new moves. It also features Campaign Mode, a 25-game mode focused on building your own team by buying players and items; and All-Star Mode, where you can play exhibition matches against the AI or other players.' FROM games WHERE igdb_id = 128381 ON CONFLICT (game_id, language_code) DO NOTHING;
