INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neon Wars', 'Neon Wars is an arcade game where vivid graphics, great music and exciting game play combine to create an amazingly new yet classic experience for the next generation of players. It''s a simple game of collecting stars and staying one step ahead of the action. Plus there''s access to powerful "special" weapons that even the odds with massive pyrotechnic special effects. The easy controls will delight the young at heart, but the action on higher difficulty levels is sure to create intense competition for the highest score.' FROM games WHERE igdb_id = 312925 ON CONFLICT (game_id, language_code) DO NOTHING;
