INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Memories Off: Sorekara Again', 'Sorekara Again is a direct sequel to Memories Off: Sorekara which takes events during the following days to the original story. Game features three separate stories (so called "after episodes"), each one centering around the time you (Isshuu Sagisawa, the same protagonist from the original story) spent with a different girl, Inori Misasagi, Miyabi Fujiwara and Karin Hanamatsuri. Gameplay itself is pretty much unchanged, the plot changes based on the choices you select during the story.' FROM games WHERE igdb_id = 64802 ON CONFLICT (game_id, language_code) DO NOTHING;
