INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kashimashi Girl Meets Girl: Hajimete no Natsu Monogatari', 'A visual novel based on the popular yuri manga Kashimashi. The game operates as a side story to the events of the manga, and covers protagonist Hazumu''s first summer vacation following the freak accident that saw them transform from a boy into a girl. As Hazumu, the player has the chance to build friendships with various characters from the manga, as well as newcomers like Haneru, a childhood friend of Hazumu''s, and Kakeno, the daughter of the inn where the characters spend the summer..' FROM games WHERE igdb_id = 127900 ON CONFLICT (game_id, language_code) DO NOTHING;
