INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'IHRA Drag Racing: Sportsman Edition', 'IHRA Sportsman marks a new direction for the popular IHRA series, with its new racing rule set and gameplay completely redesigned from the ground up. IHRA Sportsman utilizes the Official IHRA Bracket Racing rule set of the Sportsman Series - featuring Top Sportsman and Top Dragster car classes. Designed to appeal to the casual racer along with the drag racing enthusiast, the game will offer a quick play Arcade mode along with a detailed simulation mode that allows you to experience the excitement and challenge of the IHRA Sportsman 12-event season. Players will earn money, buy and unlock new higher quality parts and cars as they progress towards the IHRA Sportsman Championship. You can fully customize 60 accurate and detailed vehicles in the garage and paint shop and race on 22 different tracks, including 11 official IHRA tracks and 11 original, fantasy-style tracks.' FROM games WHERE igdb_id = 20547 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 20547 AND ge.slug = 'racing' ON CONFLICT DO NOTHING;
