INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beggar Prince', 'The snobby, selfish prince of Shatt Kingdom unknowingly aids a great threat to his world after he switches places with a beggar who looks just like him. Wanting only to escape the daily drudgery of his palace life, he has no idea what evil lies in wait around every corner. This careless brat of a boy is now the last chance for his kingdom to remain in peace, rather than be enveloped in chaos. Guide him on his way to learning the path of a true prince, and save his world from sinking into darkness.' FROM games WHERE igdb_id = 45765 ON CONFLICT (game_id, language_code) DO NOTHING;
