INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puyo Puyo Zurashi', 'Puyo Puyo Zurashi was the third mobile game as a remake of Sega and Sonic Team''s original Puyo Puyo Fever made by Sega and Sonic Cafe. This game was released for the Pocket PC as a downloadable game in Japan on October 20, 2006. Unlike all the games in the series so far, this game was never released out of Japan.' FROM games WHERE igdb_id = 251502 ON CONFLICT (game_id, language_code) DO NOTHING;
