INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Seiken Densetsu: Friends of Mana', 'Seiken Densetsu: Friends of Mana was released in Japan on October 18th, 2006, as the second installment of the World of Mana Mobile series, with the mobile remake of “Seiken Densetsu: Final Fantasy Gaiden” being the first installment. It takes place 10 years before the events of Legend of Mana for the Playstation, and is the first Network RPG in the series. There is a monthly fee to pay for the game of 525 yen (tax included, which works out at just over USD$4).' FROM games WHERE igdb_id = 287438 ON CONFLICT (game_id, language_code) DO NOTHING;
