INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nra-gun-club', 20575, '2006-10-21', 20, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co59vh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qgkn5fbzki4qjo8pyxa7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NRA Gun Club', 'This non-violent target shooter allows gamers to enter the shooting range, steady their nerves, and take aim at the bull''s-eye. The game puts over one hundred faithfully recreated firearms in the hands of the player who can try his or her skill in a wide range of immersive 3D practice environments, from indoor ranges with paper targets, to hillsides with watermelons or flying sporting clays. A certification mode challenges would-be sharpshooters'' skills, and the game also boasts detailed descriptions and information for every firearm.' FROM games WHERE igdb_id = 20575 ON CONFLICT (game_id, language_code) DO NOTHING;
