INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World War II Combat: Iwo Jima', 'World War II Combat: Iwo Jima is a budget-priced first-person shooter developed by Direct Action Games and published by Groove Games. Like its predecessor, World War II Combat: Road to Berlin, it received extremely negative reviews from reviewers and users alike. It suffered from many of the same problems of the first game.' FROM games WHERE igdb_id = 6242 ON CONFLICT (game_id, language_code) DO NOTHING;
