INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lucinda Green''s Equestrian Challenge', 'In Lucinda Green''s Equestrian Challenge, you''ll create the perfect horse to be your partner in play, practice and competition. You''ll form strong bonds with your horse as you feed, groom and train to perfect your show skills. The more you train with your horse, the better it will perform as you win your way to prestigious international competitions of Show Jumping, Dressage and Cross Country.' FROM games WHERE igdb_id = 43254 ON CONFLICT (game_id, language_code) DO NOTHING;
