INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'That''s So Raven: Psychic on the Scene', 'That''s So Raven: Psychic on the Scene is a point-and-click video game that is based on the TV series That''s So Raven. In the video game, Raven has to stop the Thompson theater from closing.
